	{{#if results.length > 0 }}
	<div class="divIdentifyResultsLayerContainer">
		<div class="divIdentifyResultsListLayerHeader">
			{{=layerTitle}} <input type="checkbox" checked="checked" class="chkIdentifyResultsLayer"/>
		</div>
		<!-- draw the headers -->
		<table>
		<thead>
			<tr>
			{{#each headers}}
				<th>{{=$view.data}}</th>
			{{/each}}
			</tr>
		</thead><tbody>
			{{#each results}}
				<tr class="{{=$ctx.createZebraClasses($itemNumber)}}">
				{{#each values}}
					{{#if $view.data == '__EMPTY__VALUE__'}}
						<td></td>
					{{else}}
						{{* if (/.ipx$/.test($view.data)) { }}
							<td><a href="#" data-href="/peopleforms/mo4/ipix/ipix_frame.php?url={{* result += $view.data; }}" class="clickable fancybox toggle_panel">Photo Link</a></td>
						{{* } else if (/(.jpg$)|(.gif$)|(.png$)/i.test($view.data)) { }}
							<td><a href="#" data-href="{{* result += $view.data; }}" class="clickable fancybox toggle_panel">Image Link</a></td>
						{{* } else if (!(/^</.test($view.data)) ){ }}
							<td title="{{* result += $view.data; }}">{{* result += $view.data; }}</td>
						{{* } else { }}
							<td>{{* result += $view.data; }}</td>
						{{* } }}
					{{/if}}
				{{/each}}
				</tr>
			{{/each}}
		</tbody></table>
	</div>
	{{/if}}



	<div class="divIdentifyResultsLayerContainer">
		{{#if results.length == 0}}
		<!-- If there are no results, say so.  -->
		<div class="identifyResultsNoneFound">No Results Found</div>

		{{else}}
		<!-- There are results, so draw the headers -->
		<table>
		<tbody>
			{{#each headers}}
				<tr>
					<td>{{=$view.data}}</td>
					{{* if ($view.parent.parent.data.results[0].values[$view.itemNumber-1] == '__EMPTY__VALUE__') { }}
						<td></td>
					{{* } else if (/.ipx$/.test($view.parent.parent.data.results[0].values[$view.itemNumber-1])) { }}
						<td><a href="#" data-href="/peopleforms/mo4/ipix/ipix_frame.php?url={{* result += $view.parent.parent.data.results[0].values[$view.itemNumber-1]; }}" class="clickable fancybox toggle_panel">Photo Link</a></td>
					{{* } else if (/(.jpg$)|(.gif$)|(.png$)/i.test($view.parent.parent.data.results[0].values[$view.itemNumber-1])) { }}
						<td><a href="#" data-href="{{* result += $view.parent.parent.data.results[0].values[$view.itemNumber-1]; }}" class="clickable fancybox toggle_panel"><img src="{{* result += $view.parent.parent.data.results[0].values[$view.itemNumber-1]; }}" style="width:110px" /></a></td>
					{{* } else if (!( /^</.test($view.parent.parent.data.results[0].values[$view.itemNumber-1]) ) ) { }}
						<td title="{{* result += $view.parent.parent.data.results[0].values[$view.itemNumber-1]; }}" >{{* result += $view.parent.parent.data.results[0].values[$view.itemNumber-1]; }}</td>
					{{* } else { }}
						<td>{{* result += $view.parent.parent.data.results[0].values[$view.itemNumber-1]; }}</td>
					{{* } }}
				</tr>
			{{/each}}
		</tbody></table>
		{{/if}}
	</div>



